def _parse_budget(raw: str | None) -> dict[str, int]:
    if not raw:
        return {"max_sources": 12, "max_ranges": 40}
    parsed = {"max_sources": 12, "max_ranges": 40}
    for part in raw.split(","):
        if not part.strip() or "=" not in part:
